findings.fix:
data "google_project" "current" {}

resource "google_project_service_identity" "datafusion" {
  provider = google-beta
  project  = data.google_project.current.project_id
  service  = "datafusion.googleapis.com"
}

resource "google_kms_crypto_key_iam_member" "datafusion" {
  crypto_key_id = google_kms_crypto_key.datafusion.id
  role          = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member        = "serviceAccount:${google_project_service_identity.datafusion.email}"
}

module "datafusion" {
  source        = "../../"
  name          = "example-instance"
  region        = "europe-west2"
  network       = google_compute_network.private.name
  ip_allocation = "10.92.48.0/22"
  crypto_key_reference = google_kms_crypto_key.datafusion.id

  depends_on = [google_kms_crypto_key_iam_member.datafusion]
}

output "p4_service_account" {
  value       = google_data_fusion_instance.main.p4_service_account
  description = "Data Fusion service agent email; grant this roles/cloudkms.cryptoKeyEncrypterDecrypter on the CMEK key"
}

variable "type" {
  type        = string
  description = "Data Fusion instance tier"
  default     = "BASIC"

  validation {
    condition     = contains(["BASIC", "ENTERPRISE", "DEVELOPER"], var.type)
    error_message = "var.type must be one of BASIC, ENTERPRISE, DEVELOPER"
  }
}

output "service_endpoint" {
  value       = google_data_fusion_instance.main.service_endpoint
  description = "Endpoint on which the Data Fusion UI and REST APIs are accessible"
}

output "api_endpoint" {
  value       = google_data_fusion_instance.main.api_endpoint
  description = "Endpoint for REST API access"
}
